public static void handleActiveKeys(Minecraft minecraft) {
	Player player = Minecraft.getInstance().player;
	if (player == null || !player.isAlive()) return;
	Set<Active.Key> addedKeys = new HashSet<>();
	Set<Active.Key> removedKeys = new HashSet<>();
	HashMap<String, Boolean> currentKeyBindingStates = new HashMap<>();
	KeyPressComponent component = ApugliEntityComponents.KEY_PRESS_COMPONENT.get(player);
	if (!component.getKeysToCheck().isEmpty()) {
		if (!ApoliClientAccessor.getInitializedKeyBindingMap()) {
			ApoliClientAccessor.setInitializedKeyBindingMap(true);
			Minecraft client = Minecraft.getInstance();
			for (int i = 0; i < client.options.keyMappings.length; i++) {
				ApoliClientAccessor.apugli$getIdToKeybindingMap().put(client.options.keyMappings[i].getName(), client.options.keyMappings[i]);
			}
		}
		component.getKeysToCheck().forEach(key -> {
			KeyMapping keyBinding = ApoliClientAccessor.apugli$getIdToKeybindingMap().get(key.key);
			if (keyBinding != null) {
				if (!currentKeyBindingStates.containsKey(key.key)) {
					currentKeyBindingStates.put(key.key, keyBinding.isDown());
				}
				if (currentKeyBindingStates.getOrDefault(key.key, false) && (key.continuous || !lastKeyBindingStates.getOrDefault(key.key, false))) {
					component.addKey(key);
					if (!lastKeyBindingStates.getOrDefault(key.key, false)) {
						addedKeys.add(key);
					}
				} else if (!currentKeyBindingStates.getOrDefault(key.key, false) && lastKeyBindingStates.getOrDefault(key.key, false)) {
					component.removeKey(key);
					removedKeys.add(key);
				}
			}
		});
		ApugliPackets.sendC2S(new UpdateKeysPressedPacket(addedKeys, removedKeys));
	}
	lastKeyBindingStates = currentKeyBindingStates;
}

@Override
public void setPreviouslyUsedKeys() {
    this.previouslyUsedKeys = this.currentlyUsedKeys.stream().filter(key -> key.continuous).collect(Collectors.toSet());
}

@Override
public void tick() {
    int powerSize = PowerHolderComponent.KEY.get(this.provider).getPowers(Power.class, true).size();
    if (this.previousPowerSize != powerSize) {
        this.keysToCheck.clear();
        this.previouslyUsedKeys.clear();
        this.currentlyUsedKeys.clear();
    }
    this.previousPowerSize = powerSize;
}

@Override
public void addKey(Active.Key key) {
    this.currentlyUsedKeys.add(key);
}

@Override
public void removeKey(Active.Key key) {
    this.currentlyUsedKeys.remove(key);
}

public boolean check(SerializableData.Instance data, Entity entity) {
    if (entity instanceof Player player) {
        Services.PLATFORM.updateKeys(data, player);
        return Services.PLATFORM.isCurrentlyUsingKey(data, player);
    }
    return false;
}

@Override
public void updateKeys(SerializableData.Instance data, Player player) {
    if (player.level().isClientSide() && !(player.isLocalPlayer())) return;

    KeyPressComponent component = ApugliEntityComponents.KEY_PRESS_COMPONENT.get(player);
    Active.Key key = data.get("key");
    if (!component.getKeysToCheck().contains(key)) {
        component.addKeyToCheck(key);
        if (!player.level().isClientSide() && player instanceof ServerPlayer serverPlayer) {
            ApugliPackets.sendS2C(new AddKeyToCheckPacket(serverPlayer.getId(), key), serverPlayer);
        }
    }
}

@Override
public boolean isCurrentlyUsingKey(SerializableData.Instance data, Player player) {
    KeyPressComponent component = ApugliEntityComponents.KEY_PRESS_COMPONENT.get(player);
    Active.Key key = data.get("key");
    return component.getCurrentlyUsedKeys().contains(key);
}

